class CompileTimeMath {
private:
    // C++14+ allows simple loops and variables
    static constexpr int compute_power(int base, int exp) {
        int result = 1;
        for (int i = 0; i < exp; ++i) {
            result *= base;
        }
        return result;
    }

public:
    // Constants used for calculation
    static constexpr int BASE = 3;
    static constexpr int POWER = 4;

    // Result must be computed at compile time (3^4 = 81)
    static constexpr int RESULT = compute_power(BASE, POWER);
};

// Usage guarantees compile-time constant evaluation
int array_size[CompileTimeMath::RESULT];
// array_size[81]
